--
-- Table structure for table `designs`
--

CREATE TABLE `designs` (
  `_id` varchar(36) NOT NULL,
  `id` varchar(255) NOT NULL,
  `userID` varchar(255) NOT NULL,
  `name` varchar(255) NOT NULL,
  `url` varchar(255) NOT NULL,
  `tags` text DEFAULT NULL COMMENT 'Stores an array of string tags.',
  `createdAt` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  `updatedAt` datetime(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6)
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

-- --------------------------------------------------------

--
-- Table structure for table `orders`
--

CREATE TABLE `orders` (
  `_id` varchar(36) NOT NULL,
  `id` varchar(255) NOT NULL,
  `userID` varchar(255) NOT NULL,
  `flutterwaveRef` varchar(255) DEFAULT NULL,
  `paystackRef` varchar(255) DEFAULT NULL,
  `authorization_url` varchar(255) DEFAULT NULL,
  `accessCode` varchar(255) DEFAULT NULL,
  `tx_ref` varchar(255) DEFAULT NULL,
  `isPaid` tinyint(4) NOT NULL DEFAULT 0,
  `totalPrice` decimal(10,2) NOT NULL,
  `imageUrls` text DEFAULT NULL,
  `status` varchar(255) NOT NULL DEFAULT 'pending',
  `address` varchar(255) NOT NULL,
  `createdAt` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  `updatedAt` datetime(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6),
  `products` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`products`)),
  `orderDetails` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`orderDetails`)),
  `shippingAddress` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`shippingAddress`)),
  `deliveryFee` decimal(10,2) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

