('177bcd6f-1ae6-43d7-bfb6-c14a5bec922d', 'PDT764931', 1, 'Awaits Sweatshirt', '011da6c5-578a-43ec-937b-c3f811e6e202', 'A classic grey crewneck sweatshirt with a simple yet inspiring line-art graphic. The design shows a rising or setting sun behind a mountain range, with the word \'EXPLORE\' in a bold, arched font above and the tagline \'The World Awaits\' below.', 'http://api.smartprints.ng/v1/upload/file/458-306904-1762012258753-Google_AI_Studio_2025-10-17T00_11_51.463Z.png', 34555.00, NULL, 30000.00, 1, NULL, 'Sweatshirt', 0, 'store', NULL, NULL, NULL, 'active', NULL, '', '2025-11-01 17:51:03.822637', '2026-01-28 09:52:40.000000', NULL, NULL, '[{\"name\":\"Cardinal Red\",\"hex\":\"#DC2626\",\"className\":\"bg-red-600\"},{\"name\":\"Black\",\"hex\":\"#000000\",\"className\":\"bg-black\"}]', '[{\"name\":\"XS\",\"label\":\"Extra Small\",\"inStock\":true},{\"name\":\"L\",\"label\":\"Large\",\"inStock\":true}]', NULL, 1, NULL, NULL, 0, 0, NULL, NULL, 0, 0),
